// COR-09/13/15 — public quarantine. The rent-control surface is refused (HTTP 503) and, since
// D-40, its quarantine and reason are served by `GET /v1/datasets` and rendered in the detail of its
// source in « Données & méthode » (the former detail page now redirects there, H4; DatasetDetail since
// 04.5-11). The detail is rendered from the served answer (fixture generated by the backend, pinned
// to the catalogue).
import { render } from '@testing-library/svelte';
import { describe, expect, it } from 'vitest';
import DatasetDetail from '$lib/components/DatasetDetail.svelte';
import type { DatasetPublic } from '$lib/api/datasets';
import datasetsApi from '$lib/data/__fixtures__/datasets-api.json';
import responses from '$lib/data/__fixtures__/quarantined-surfaces.json';

const ENCADREMENT = (datasetsApi.donnees as DatasetPublic[]).find(
	(jeu) => jeu.nom === 'encadrement_loyers'
)!;

describe('COR-09/13/15 — public quarantine', () => {
	it('renders the served quarantine without a fabricated rent or geographic attribution', () => {
		expect(ENCADREMENT.statut).toBe('quarantined');
		const { container } = render(DatasetDetail, {
			props: { jeu: ENCADREMENT, departementsInstance: ['44', '85'] }
		});
		const text = container.textContent ?? '';
		expect(text).toContain('Non qualifié');
		expect(text).toContain('Service indisponible');
		expect(text).toContain('HTTP 503');
		expect(text).toContain("ne signifie pas absence d'encadrement");
		expect(text).toContain('sélection manuelle');
		expect(text).toContain('centroïde');
		expect(text).not.toContain('Graslin');
		expect(text).not.toContain('13.5');
		expect(text).not.toContain('loyer_reference_majore');
		expect(text).not.toContain('paginées par curseur');
		expect(text).not.toContain('Importé sur cette instance');
	});

	it('agrees with the refusal of the rent-control route itself', () => {
		expect(responses.encadrement.status).toBe(503);
		expect(responses.encadrement.payload.statut).toBe('indisponible');
		expect(responses.encadrement.payload.donnees).toEqual([]);
		expect(responses.encadrement.payload.raison).toContain('ne signifie pas absence');
	});

	it('keeps both scoring routes unavailable and unable to produce CSV', () => {
		for (const response of [responses.scoring, responses.csv]) {
			expect(response.status).toBe(503);
			expect(response.payload.statut).toBe('indisponible');
			expect(response.payload.donnees).toEqual([]);
			expect(response.payload.raison).toContain('ne signifie pas absence');
			expect(JSON.stringify(response.payload)).not.toContain('prix_achat');
		}
	});
});
